      "path": "packages/plugin/package.json",
      "content": "{\n  \"name\": \"@memef1f1y/dsh-plugin-adapter\",\n  \"version\": \"0.4.0\",\n  \"description\": \"Free OpenCode Zen models for DeepSeek Harness (DSH): native dsh-llm adapter plugin, no API key.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\",\n    \"./client\": \"./lib/client.js\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"LICENSE\",\n    \"tsdown.client.config.ts\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/1624318455/dsh-plugin-adapter.git\"\n  },\n  \"homepage\": \"https://github.com/1624318455/dsh-plugin-adapter#readme\",\n  \"bugs\": \"https://github.com/1624318455/dsh-plugin-adapter/issues\",\n  \"author\": \"1624318455 (fork of FishBottle7/opencode2dsh)\",\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"slots\",\n        \"locale\",\n        \"configForms\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown src/index.ts --format esm --dts --out-dir lib --no-clean\",\n    \"prepack\": \"node -e \\\"require('fs').rmSync('lib',{recursive:true,force:true})\\\" && pnpm build && pnpm build:client && node ../../scripts/prepare-package.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"node --test \\\"test/*.test.ts\\\"\",\n    \"build:client\": \"tsdown -c tsdown.client.config.ts\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"opencode\",\n    \"opencode-zen\",\n    \"cordis\",\n    \"cordis-plugin\",\n    \"llm-adapter\",\n    \"llm-provider\",\n    \"free-models\",\n    \"free-llm\",\n    \"llm\",\n    \"ai-models\",\n    \"typescript\",\n    \"nodejs\"\n  ],\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"@earendil-works/pi-ai\": \"^0.82.1\",\n    \"undici\": \"^8.10.1\",\n    \"yaml\": \"^2.9.0\"\n  },\n  \"pnpm\": {\n    \"ignoredBuiltDependencies\": [\n      \"@google/genai\",\n      \"protobufjs\"\n    ]\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-credentials\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.0-rc.2\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.31\",\n    \"lightningcss\": \"1.32.0\",\n    \"react\": \"^18.3.1\",\n    \"tsdown\": \"^0.15.0\",\n    \"typescript\": \"^5.9.0\"\n  }\n}\n"
